<?php

declare(strict_types=1);

namespace WorkerAdmin\Application\Order;

use WorkerAdmin\Contracts\PlatformOrderAdminRepository;
use WorkerAdmin\Contracts\SettingsProvider;
use WorkerAdmin\Domain\Order\OrderOperationException;
use WorkerAdmin\Domain\Order\PlatformOrderSettlementPolicy;

final class PlatformOrderAdmin
{
    private const DEFAULT_TENCENT_MAP_KEY = '32CBZ-FEPK6-POMSA-MCDE2-M2MIK-ZOBK2';
    private PlatformOrderAdminRepository $repository;
    private SettingsProvider $settings;
    private PlatformOrderSettlementPolicy $settlementPolicy;
    public function __construct(PlatformOrderAdminRepository $repository, SettingsProvider $settings){$this->repository=$repository;$this->settings=$settings;$this->settlementPolicy=new PlatformOrderSettlementPolicy();}
    public function dashboard(): array {$data=$this->repository->dashboard();$data['defaultExtraRate']=max(0,min(10000,(int)$this->settings->get('platform_order.extra_income_rate_bp',2000)));$data['defaultBookingFee']=max(0,(int)$this->settings->get('order.booking_fee_cents',5000));$data['freezeDays']=max(0,min(365,(int)$this->settings->get('platform_order.worker_balance_freeze_days',0)));$data['mapKey']=trim((string)$this->settings->get('map.tencent_key',self::DEFAULT_TENCENT_MAP_KEY));return $data;}
    public function create(array $input,int $adminId): int
    {
        $userId=max(0,(int)($input['user_id']??0));$categoryId=max(0,(int)($input['category_id']??0));if($categoryId<1)throw new OrderOperationException('请选择有效服务类目。','PLATFORM_CATEGORY_REQUIRED',422);
        $customerFlow=(string)($input['customer_flow_mode']??'platform_managed');if(!in_array($customerFlow,['platform_managed','miniapp_booking'],true))throw new OrderOperationException('客户参与方式无效。','PLATFORM_CUSTOMER_FLOW_INVALID',422);if($customerFlow==='miniapp_booking'&&$userId<1)throw new OrderOperationException('选择“小程序支付预约费”时必须先关联已有客户账号。','PLATFORM_USER_REQUIRED_FOR_BOOKING',422);
        $fulfillmentMode=(string)($input['fulfillment_mode']??'direct_install');if(!in_array($fulfillmentMode,['direct_install','measure_then_install'],true))throw new OrderOperationException('履约方式无效。','PLATFORM_FULFILLMENT_MODE_INVALID',422);
        $title=mb_substr(trim((string)($input['title']??'')),0,160);$description=mb_substr(trim((string)($input['description']??'')),0,2000);$city=mb_substr(trim((string)($input['city']??'')),0,64);$district=mb_substr(trim((string)($input['district']??'')),0,64);$address=mb_substr(trim((string)($input['address']??'')),0,500);$contactName=mb_substr(trim((string)($input['contact_name']??'')),0,80);$contactMobile=preg_replace('/\D+/','',(string)($input['contact_mobile']??''))?:'';if($title===''||$city===''||$district===''||$address==='')throw new OrderOperationException('请完整填写订单标题、城市、区域和施工地址。','PLATFORM_ORDER_FIELDS_REQUIRED',422);if($contactName===''||preg_match('/^1\d{10}$/',$contactMobile)!==1)throw new OrderOperationException('请填写有效联系人和 11 位手机号。','PLATFORM_CONTACT_INVALID',422);
        [$lat,$lng]=$this->coordinatePair($input['map_lat']??null,$input['map_lng']??null);$mapPointName=mb_substr(trim((string)($input['map_point_name']??'')),0,160);$mapPointAddress=mb_substr(trim((string)($input['map_point_address']??'')),0,255);$mapKey=trim((string)$this->settings->get('map.tencent_key',self::DEFAULT_TENCENT_MAP_KEY));
        $pricingMode=(string)($input['customer_pricing_mode']??'fixed_total');if(!in_array($pricingMode,['fixed_total','itemized'],true))throw new OrderOperationException('客户计价方式无效。','PLATFORM_PRICING_MODE_INVALID',422);$items=$pricingMode==='itemized'?$this->pricingItems($input):[];$customerTotal=$pricingMode==='itemized'?array_sum(array_column($items,'amount_cents')):$this->moneyToCents((string)($input['customer_total']??''));if($customerTotal<=0||$customerTotal>100000000)throw new OrderOperationException('客户成交金额必须大于 0 且不能超过 100 万元。','PLATFORM_CUSTOMER_TOTAL_INVALID',422);
        $defaultBookingFee=max(0,(int)$this->settings->get('order.booking_fee_cents',5000));if($customerFlow==='platform_managed'&&array_key_exists('booking_fee',$input)){$bookingFeeRaw=trim(str_replace([',','￥','¥','元'],'',(string)$input['booking_fee']));if(!preg_match('/^(\d{1,8})(?:\.(\d{1,2}))?$/D',$bookingFeeRaw))throw new OrderOperationException('预约费金额格式不正确。','PLATFORM_BOOKING_AMOUNT_INVALID',422);$bookingFee=$this->moneyToCents($bookingFeeRaw);}elseif($customerFlow==='platform_managed'){$bookingFee=0;}else{$bookingFee=$defaultBookingFee;}if($bookingFee<0||$bookingFee>$customerTotal)throw new OrderOperationException('预约费不能超过客户成交金额。','PLATFORM_TOTAL_BELOW_BOOKING',422);
        $dispatchMode=(string)($input['dispatch_mode']??'multi_quote');if(!in_array($dispatchMode,['multi_quote','single_grab'],true))throw new OrderOperationException('师傅成交方式无效。','PLATFORM_DISPATCH_MODE_INVALID',422);$settlementMode=(string)($input['worker_settlement_mode']??PlatformOrderSettlementPolicy::MODE_WORKER_COLLECT);if(!in_array($settlementMode,[PlatformOrderSettlementPolicy::MODE_WORKER_COLLECT,PlatformOrderSettlementPolicy::MODE_PLATFORM_BALANCE],true))throw new OrderOperationException('工费结算方式无效。','PLATFORM_SETTLEMENT_MODE_INVALID',422);$workerLabor=$dispatchMode==='single_grab'?$this->moneyToCents((string)($input['worker_labor']??'')):0;if($dispatchMode==='single_grab'&&$workerLabor<=0)throw new OrderOperationException('一口价抢单必须填写师傅工费。','PLATFORM_LABOR_REQUIRED',422);if($settlementMode===PlatformOrderSettlementPolicy::MODE_WORKER_COLLECT&&$workerLabor>0)$this->settlementPolicy->settlement($customerTotal,$workerLabor,$bookingFee,$settlementMode);
        $defaultRate=max(0,min(10000,(int)$this->settings->get('platform_order.extra_income_rate_bp',2000)));$extraIncomeMode=(string)($input['extra_income_mode']??'rate');if(!in_array($extraIncomeMode,['rate','fixed'],true))throw new OrderOperationException('加项平台收入方式无效。','PLATFORM_EXTRA_INCOME_MODE_INVALID',422);if($extraIncomeMode==='fixed'){$fixedIncome=$this->moneyToCents((string)($input['extra_income_fixed']??''));if($fixedIncome<0||$fixedIncome>100000000)throw new OrderOperationException('固定平台收入金额不能超过 100 万元。','PLATFORM_EXTRA_FIXED_INVALID',422);$extraRateBp=PlatformOrderSettlementPolicy::EXTRA_INCOME_FIXED_OFFSET+$fixedIncome;}else{$extraRateBp=array_key_exists('extra_income_rate_percent',$input)?$this->percentToBasisPoints((string)$input['extra_income_rate_percent']):$defaultRate;}$freezeDays=max(0,min(365,(int)$this->settings->get('platform_order.worker_balance_freeze_days',0)));
        return $this->repository->create(['user_id'=>$userId,'customer_flow_mode'=>$customerFlow,'fulfillment_mode'=>$fulfillmentMode,'category_id'=>$categoryId,'title'=>$title,'description'=>$description,'city'=>$city,'district'=>$district,'address'=>$address,'lat'=>$lat,'lng'=>$lng,'map_point_name'=>$mapPointName,'map_point_address'=>$mapPointAddress,'map_key'=>$mapKey,'contact_name'=>$contactName,'contact_mobile'=>$contactMobile,'customer_pricing_mode'=>$pricingMode,'customer_total_cents'=>$customerTotal,'pricing_items'=>$items,'booking_fee_cents'=>$bookingFee,'dispatch_mode'=>$dispatchMode,'worker_settlement_mode'=>$settlementMode,'worker_labor_cents'=>$workerLabor,'extra_income_rate_bp'=>$extraRateBp,'worker_balance_freeze_days'=>$freezeDays],$adminId);
    }
    public function publish(int $orderId,int $adminId):void{if($orderId<1)throw new OrderOperationException('平台承接单不存在。','PLATFORM_ORDER_NOT_FOUND',404);$days=max(1,min(30,(int)$this->settings->get('order.auto_cancel_days',7)));$this->repository->publish($orderId,$adminId,$days);}public function selectQuote(int $orderId,int $quoteId,int $adminId):void{if($orderId<1||$quoteId<1)throw new OrderOperationException('请选择有效平台承接单和师傅报价。','PLATFORM_QUOTE_REQUIRED',422);$this->repository->selectQuote($orderId,$quoteId,$adminId);}public function createInvite(int $orderId,int $adminId,int $validDays):array{if($orderId<1)throw new OrderOperationException('平台承接单不存在。','PLATFORM_ORDER_NOT_FOUND',404);return $this->repository->createInvite($orderId,$adminId,max(1,min(30,$validDays)));}public function revokeInvite(int $orderId,int $inviteId,int $adminId):void{if($orderId<1||$inviteId<1)throw new OrderOperationException('邀请记录不存在。','PLATFORM_INVITE_NOT_FOUND',404);$this->repository->revokeInvite($orderId,$inviteId,$adminId);}
    private function pricingItems(array $input):array{$descriptions=is_array($input['item_description']??null)?$input['item_description']:[];$quantities=is_array($input['item_quantity']??null)?$input['item_quantity']:[];$units=is_array($input['item_unit']??null)?$input['item_unit']:[];$prices=is_array($input['item_unit_price']??null)?$input['item_unit_price']:[];$notes=is_array($input['item_note']??null)?$input['item_note']:[];$items=[];foreach($descriptions as $index=>$rawDescription){$description=mb_substr(trim((string)$rawDescription),0,160);if($description==='')continue;$quantityMilli=$this->quantityToMilli((string)($quantities[$index]??''));$unitPrice=$this->moneyToCents((string)($prices[$index]??''));if($quantityMilli<=0||$unitPrice<0)throw new OrderOperationException('开单明细“'.$description.'”的数量或单价不正确。','PLATFORM_ITEM_INVALID',422);$amount=intdiv($quantityMilli*$unitPrice+500,1000);if($amount>100000000)throw new OrderOperationException('单项金额过大。','PLATFORM_ITEM_TOO_LARGE',422);$items[]=['description'=>$description,'quantity'=>number_format($quantityMilli/1000,3,'.',''),'quantity_milli'=>$quantityMilli,'unit'=>mb_substr(trim((string)($units[$index]??'')),0,24),'unit_price_cents'=>$unitPrice,'amount_cents'=>$amount,'note'=>mb_substr(trim((string)($notes[$index]??'')),0,500)];}if(!$items)throw new OrderOperationException('明细计价至少填写一个有效施工项目。','PLATFORM_ITEMS_REQUIRED',422);return $items;}
    private function coordinatePair($latRaw,$lngRaw):array{$latText=trim(is_scalar($latRaw)?(string)$latRaw:'');$lngText=trim(is_scalar($lngRaw)?(string)$lngRaw:'');if($latText===''||$lngText==='')throw new OrderOperationException('平台承接单必须先完成地图选点；详细施工地址可在选点后继续修改。','PLATFORM_MAP_REQUIRED',422);if(!is_numeric($latText)||!is_numeric($lngText))throw new OrderOperationException('地图选点坐标不完整，请重新选点。','PLATFORM_MAP_COORDINATE_INVALID',422);$lat=(float)$latText;$lng=(float)$lngText;if(!is_finite($lat)||!is_finite($lng)||$lat<-90||$lat>90||$lng<-180||$lng>180)throw new OrderOperationException('地图选点坐标超出有效范围，请重新选择。','PLATFORM_MAP_COORDINATE_INVALID',422);return[$lat,$lng];}
    private function percentToBasisPoints(string $value):int{$value=trim($value);if(!preg_match('/^(?:100(?:\.0{1,2})?|\d{1,2}(?:\.\d{1,2})?)$/D',$value,$parts))throw new OrderOperationException('订单外加项平台收入比例必须为 0 至 100，最多两位小数。','PLATFORM_EXTRA_RATE_INVALID',422);[$whole,$fraction]=array_pad(explode('.',$value,2),2,'');return min(10000,((int)$whole)*100+(int)str_pad($fraction,2,'0'));}
    private function quantityToMilli(string $value):int{$value=trim($value);if(!preg_match('/^(\d{1,9})(?:\.(\d{1,3}))?$/D',$value,$parts))return 0;return((int)$parts[1])*1000+(int)str_pad($parts[2]??'',3,'0');}
    private function moneyToCents(string $value):int{$value=trim(str_replace([',','￥','¥','元'],'',$value));if(!preg_match('/^(\d{1,8})(?:\.(\d{1,2}))?$/D',$value,$parts))return 0;return((int)$parts[1])*100+(int)str_pad($parts[2]??'',2,'0');}
}
